//! Actions-only actual group-management frame prefix/cancellation/config/Join.
use super::*;
use n::group_management::{GroupWriteOperation as Op,NativeGroupManagementConfig as GPolicy,PublicProperty,PropertyValue};
use n::relation_journal::{RelationConfiguration,RelationIntent,IntentAdmission};
async fn gp(handle:&RuntimeHandle,who:&AttemptOwner,scope:&RpcConnectionScope,temp:&TempDatabase,run:Arc<n::account_runs::RunToken>,gate:Arc<ImReceiptGate>,op:Op)->(Arc<RelationIntent>,Arc<RelationAction>,Arc<RelationPermit>){temp.database.with_conn(n::group_management_store::initialize_schema).unwrap();let fields=[PublicProperty{key:"Name",value:PropertyValue::Text("private-group")}];let policy=GPolicy{set_properties:true,disband:true};let message=Arc::new(RelationMessage::capture_management(scope,b"1-2",op,if op==Op::SetProperties{&fields}else{&[]},NONCE,policy).unwrap());let cfg=Arc::new(temp.database.with_conn(|c|RelationConfiguration::capture(c,run.line_id(),run.revision(),Some(scope))).unwrap());let IntentAdmission::Fresh(i)=RelationIntent::capture(temp.database.clone(),run,who.clone(),scope.clone(),message,cfg,gate,Instant::now()+Duration::from_secs(3)).unwrap()else{panic!()};let commands=handle.command_handle();let b=bounded(commands.original_im_binding(who,scope)).await.unwrap();let id=bounded(commands.original_relation_identity(who,scope)).await.unwrap();let PreparedRelation::Fresh(a)=i.bind(b,id,policy).unwrap()else{panic!()};let p=a.permit(policy).unwrap();(i,a,p)}
async fn prefix_case(mode:u8){let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let route=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let peer=async move{let mut p=CommonPeer::open(listener,server).await;peer_login(&mut p).await;eof(&mut p).await;};let client=async{let mut conn=connected(&route,who.clone(),Instant::now()+Duration::from_secs(6)).await;let prefix=n::router_runtime::tests::auxiliary_io::AuxiliaryIoTest::original_unarmed(1);n::common_runtime::tests::gate_auxiliary_prefix(conn.common.as_mut().unwrap(),prefix.clone());let scope=conn.connection_scope();let(mut h,mut events)=conn.attach().unwrap();auth(&h,&mut events,&who,&scope,true).await;let gate=ImReceiptGate::fresh();let(i,a,p)=gp(&h,&who,&scope,&temp,run.clone(),gate.clone(),if mode==1{Op::Disband}else{Op::SetProperties}).await;prefix.arm();let commands=h.command_handle();let mut write=Box::pin(commands.update_relations(&who,&scope,p.clone()));tokio::select!{v=&mut write=>panic!("partial {v:?}"),_=bounded(prefix.paused())=>{}}assert_eq!(prefix.accepted.load(Ordering::SeqCst),1);let before=row(&temp);assert_eq!(before,(0,Some(2),None,None));if mode==0{drop(write);}else if mode==1{gate.retire();assert!(bounded(write).await.is_err());}else{temp.database.with_conn(|c|c.execute("UPDATE app_voice_accounts SET private_config=X'00'",[]).map_err(|_|"fixture")).unwrap();assert!(bounded(write).await.is_err());}bounded(scope.closed()).await;assert!(bounded(h.close()).await.io_released());assert!(prefix.dropped.load(Ordering::SeqCst));assert_eq!(prefix.accepted.load(Ordering::SeqCst),1);assert_eq!(row(&temp),before);no_event(&temp);drop(p);drop(a);drop(i);assert_eq!(scope.native_rpc_resources(),(0,0));};tokio::join!(Box::pin(bounded(peer)),Box::pin(bounded(client)));}
#[tokio::test]async fn group_management_partial_properties_wait_drop_keeps_shared_unknown_and_joins(){Box::pin(prefix_case(0)).await;}
#[tokio::test]async fn group_management_partial_disband_parent_retirement_blocks_any_more_bytes(){Box::pin(prefix_case(1)).await;}
#[tokio::test]async fn group_management_same_revision_config_change_after_ciphertext_prefix_revokes_physical_poll(){Box::pin(prefix_case(2)).await;}
#[tokio::test]async fn group_management_submitted_disband_cancel_keeps_unknown_after_original_fd_join(){Box::pin(async{let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let route=router_policy(&cert.root,listener.local_addr().unwrap().port());let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let(who,run)=original(&temp,&cert.root);let(sent,seen)=oneshot::channel();let peer=async move{let mut p=CommonPeer::open(listener,server).await;peer_login(&mut p).await;let b=p.next().await.unwrap();assert_eq!(query(&b,"disbandOrganize.GroupServer.Group"),2);sent.send(()).unwrap();eof(&mut p).await;};let client=async{let conn=connected(&route,who.clone(),Instant::now()+Duration::from_secs(6)).await;let scope=conn.connection_scope();let(mut h,mut events)=conn.attach().unwrap();auth(&h,&mut events,&who,&scope,true).await;let(i,a,p)=gp(&h,&who,&scope,&temp,run.clone(),ImReceiptGate::fresh(),Op::Disband).await;let commands=h.command_handle();let mut write=Box::pin(commands.update_relations(&who,&scope,p.clone()));tokio::select!{v=&mut write=>panic!("unsubmitted {v:?}"),r=bounded(seen)=>r.unwrap()};drop(write);bounded(scope.closed()).await;assert!(bounded(h.close()).await.io_released());assert_eq!(row(&temp),(0,Some(2),None,None));no_event(&temp);drop(p);drop(a);drop(i);assert_eq!(scope.native_rpc_resources(),(0,0));};tokio::join!(Box::pin(bounded(peer)),Box::pin(bounded(client)));}).await;}
